    id: "agathion-bishop-agathion",
    name: "Agathion, Bishop Agathion",
    cr: 4,
    xp: 1200,
    alignment: "NG",
    size: "Medium",
    type: "outsider",
    subtype: "aquatic, extraplanar, good",
    init: 7,
    senses: "darkvision 60 ft., low-light vision, detect evil;",
    ac: 17,
    hp: 38,
    hpNotes: "7d10",
    fort: 2,
    ref: 8,
    will: 8,
    dr: "5/evil or silver;",
    immune: "electricity, petrification;",
    resist: "cold 10, sonic 10;",
