    hpNotes: "4d10+16",
    fort: 8,
    ref: 3,
    will: 6,
    dr: "5/evil or silver;",
    immune: "electricity, paralysis, petrification;",
    resist: "acid 10, cold 10, sonic 10;",
    str: 11,
