    subtype: "earth, elemental, native",
    init: 5,
    senses: "darkvision 60 ft., tremorsense 30 ft.;",
    ac: 17,
    hp: 38,
    hpNotes: "4d10+16",
    fort: 8,
    ref: 5,
    will: 2,
    immune: "elemental traits",
    str: 17,
