    ref: 18,
    will: 24,
    defensiveAbilities: "heed no call, uncanny dodge;",
    dr: "15/piercing and evil;",
    immune: "acid, cold, petrification;",
    resist: "electricity 10, fire 10;",
    space: "10 ft.,",
