    size: "Medium",
    type: "outsider",
    subtype: "incorporeal, native",
    init: 7,
    ac: 24,
    hp: 152,
    hpNotes: "16d10+64",
    fort: 14,
    ref: 12,
    will: 12,
    defensiveAbilities: "incorporeal",
    str: 0,
