    subtype: "aquatic",
    init: 4,
    senses: "darkvision 60 ft., tentacle sense 10 ft.;",
    ac: 18,
    hp: 45,
    hpNotes: "6d10+12",
    fort: 4,
    ref: 9,
    will: 6,
    space: "5 ft.",
    reach: "5 ft. (10 ft. with tentacles)",
    str: 16,
    dex: 19,
    con: 14,
    int: 9,
    wis: 12,
