    senses: "darkvision 60 ft., low-light vision;",
    ac: 20,
    hp: 74,
    hpNotes: "8d10+30",
    fort: 2,
    ref: 5,
    will: 2,
    space: "10 ft.,",
    specialAttacks: "powerful kick, trample (1d6+7, DC 21)",
    str: 24,
    dex: 13,
