    will: 6,
    defensiveAbilities: "all-around vision,",
    dr: "10/slashing;",
    immune: "plant traits;",
    resist: "acid 10, electricity 10",
    space: "15 ft.,",
    specialAttacks: "constrict (1d8+12), swallow whole (4d6 acid damage, AC 17, 17 hp)",
    str: 34,
    dex: 19,
    con: 23,
