    id: "daemon-lapsudaemon",
    name: "Daemon, Lapsudaemon",
    cr: 14,
    xp: 38400,
    alignment: "NE",
    size: "Medium",
    type: "outsider",
    subtype: "daemon, evil, extraplanar",
    init: 10,
    senses: "blindsense 200 ft., darkvision 60 ft.;",
    ac: 29,
    hp: 199,
    hpNotes: "19d10+95",
    fort: 11,
    ref: 21,
    will: 15,
    defensiveAbilities: "amorphous, vertigo’s grace;",
    dr: "10/good;",
    immune: "acid, bludgeoning, death effects, disease, poison;",
    resist: "cold 10, electricity 10, fire 10;",
    str: 18,
    dex: 31,
    con: 21,
