    fort: 17,
    ref: 25,
    will: 24,
    dr: "20/good and silver;",
    immune: "acid, charm, compulsion, death effects, disease, emotion, enchantments, mind-reading, poison;",
    resist: "cold 30, electricity 30, fire 30;",
    str: 21,
    dex: 30,
    con: 28,
    int: 25,
    wis: 28,
