    id: "demodand-squamous-demodand",
    name: "Demodand, Squamous Demodand",
    cr: 20,
    xp: 307200,
    alignment: "CE",
    size: "Gargantuan",
    type: "outsider",
    subtype: "chaotic, demodand, evil, extraplanar",
    init: 11,
    ac: 36,
    hp: 362,
    hpNotes: "29d10+203",
    fort: 23,
    ref: 23,
    will: 16,
    dr: "15/good and magic;",
    immune: "acid, poison;",
    resist: "cold 10, fire 10;",
    space: "20 ft.,",
    str: 32,
