    xp: 12800,
    alignment: "CE",
    size: "Large",
    type: "outsider",
    subtype: "chaotic, demon, evil, extraplanar",
    init: 8,
    senses: "darkvision 60 ft., scent;",
    ac: 25,
    hp: 137,
    hpNotes: "11d10+77",
    fort: 14,
    ref: 9,
    will: 10,
    defensiveAbilities: "amorphous;",
    dr: "10/good;",
    resist: "cold 10, fire 10;",
