    init: -1,
    ac: 15,
    hp: 30,
    hpNotes: "4d10+8",
    fort: 8,
    ref: 0,
    will: 5,
    dr: "5/cold iron or good;",
    immune: "electricity, poison;",
    resist: "acid 10, cold 10, fire 10;",
    str: 15,
    dex: 9,
    con: 14,
    int: 12,
