    xp: 9600,
    alignment: "LE",
    size: "Medium",
    type: "outsider",
    subtype: "devil, evil, extraplanar, incorporeal, lawful",
    init: 6,
    senses: "darkvision 60 ft., see in darkness;",
    ac: 22,
    hp: 95,
    hpNotes: "10d10+40",
    fort: 11,
    ref: 15,
    will: 7,
    dr: "10/good;",
    immune: "fire, poison;",
