    init: -2,
    ac: 21,
    hp: 125,
    hpNotes: "10d10+70",
    fort: 14,
    ref: 5,
    will: 2,
    dr: "5/good and piercing;",
    immune: "fire, poison;",
    resist: "acid 10, cold 10",
    space: "15 ft.,",
    str: 27,
    dex: 7,
    con: 24,
    int: 8,
    wis: 9,
    cha: 15,
    baseAtk: 10,
