    init: 6,
    senses: "darkvision 60 ft., see in darkness, true seeing;",
    ac: 23,
    hp: 94,
    hpNotes: "9d10+45",
    fort: 11,
    ref: 12,
    will: 7,
    dr: "5/good;",
    immune: "fire, poison;",
    resist: "acid 10, cold 10;",
    str: 20,
