    type: "outsider",
    subtype: "devil, evil, extraplanar, lawful",
    init: 3,
    ac: 17,
    hp: 16,
    hpNotes: "3d10",
    fort: 1,
    ref: 6,
    will: 4,
    dr: "5/good or silver;",
    immune: "fire, poison;",
    resist: "acid 10, cold 10",
    space: "2-1/2 ft.,",
    str: 10,
