    init: 5,
    senses: "darkvision 60 ft., low-light vision, scent, snow vision;",
    ac: 20,
    hp: 84,
    hpNotes: "8d12+32",
    fort: 10,
    ref: 7,
    will: 5,
    space: "10 ft.,",
