    size: "Large",
    type: "dragon",
    subtype: "earth",
    init: 7,
    senses: "darkvision 60 ft., greensight 60 ft. low-light vision, scent;",
    ac: 19,
    hp: 73,
    hpNotes: "7d12+28",
    fort: 9,
    ref: 8,
    will: 6,
    immune: "disease, poison, paralysis, sleep",
    space: "10 ft.,",
    specialAttacks: "predatory grab",
    str: 24,
    dex: 17,
